    def iterator(self):
        yield from RawModelIterable(self)

    def __repr__(self):
        return f"<{self.__class__.__name__}: {self.query}>"

    def __getitem__(self, k):
        return list(self)[k]

    @cached_property
    def columns(self):
        """
